        var float ret;
        if (v-multiplier < 0) { ret := (int2float(v.value_) * (1.0/(f_CMN_Pow(v-multiplier*-1))))};
        else if (v-multiplier > 0) { ret := (int2float(v.value_) * (f_CMN_Pow(v-multiplier))), } 
