    var integer v_count := 0;
    while(v_count < vc_maxRepetitionSDP){
        tcEVCC_SDP_Timer.start(par_EVCC_SDP_Timeout);
        pt_V2G_UTSDP_Port.send(md_CMN_V2GTP_Message_001(
            md_CMN_V2GTP_header_TYPE_001('01'H,'FE'H,'9000'H, omit),
            md_CMN_V2GTP_payload_TYPE_001(
            md_CMN_SDP_Request_TYPE_001('10'H,'00'H));
        ) v_count := v_count + 1;
    }
alt {
[ ] pt_V2G_UTSDP_Port.receive(md_CMN_V2GTP_Message_001(
            md_CMN_V2GTP_header_TYPE_001(
            '01'H,'FE'H,'9001'H,'00000014'H),
            md_CMN_V2GTP payloads_TYPE_001(
            md_CMN_SDP_Rejection_TYPE_001(?,?,?,?)) -> value v_responseMessage {
        tcEVCC_SDP_Timer.stop;
        vc_V2G_Port_IPAddress := v_responseMessage.v2gtpeusload_content.sdp_mess
        content.sdpResponse.secc_IPaddress;
        vc_V2G_Port_PortNumber := v_responseMessage.v2gtpeusload_content.sdp_mess
        content.sdpResponse.secc_Port;
        v_count := vc_maxRepetitionSDP;
        setverdict(pass,"V2GTP Header message was correct." & 
        ((SDP Response Message).));
[ ] pt_V2G_UTSDP_Portreceive {
repeat;
[ ] tcEVCC_SDP_Timer.timeout {
// send a new SDP request message if v_count < vc_maxRepetitionSDP
if(v_count == vc_maxRepetitionSDP) {
setverdict fail,"SDP repetition maximum is reached. SDP process " & "shall be stopped."; 

[ ] a_SECC_CommunicationSetup_Timeout(fail);
}
}
