        else { ret := int2float(v.value_; } 
    return ret;
}

function f_CMN_Pow(in integer v-multiplier) return float {
    var float ret := 10.0;
    for (var integer i:=0; i<v-multiplier-1; i=i+1) {
        ret := ret * 10.0;
    }
    return ret;
}

function f_CMN_AsbFlt(in float v_first, in float v_second) return float {
    if (v_first == v(second)) {
        return 0;
    }
    if (v_first > v(second)) {
        return v_first - v(second);
    }else {
        return v_second - v_first;
    }
}

